import{_ as r,a0 as s,w as p,s as f,ao as l,I as o,x as n,a1 as e,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"如何给任意一款 Linux 发行版添加漂亮的字体 | LCTT x X-CMD","titleTemplate":false,"description":"如何给任意一款 Linux 发行版添加漂亮的字体 | LCTT (201405) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何给任意一款 Linux 发行版添加漂亮的字体 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何给任意一款 Linux 发行版添加漂亮的字体 | LCTT (201405) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201405/How to Add Beautiful Fonts to Any Linux Distribution","title":"如何给任意一款 Linux 发行版添加漂亮的字体","tag":"201405","desc":""},"relativePath":"201405/How to Add Beautiful Fonts to Any Linux Distribution.md","filePath":"[post].md"}'),u={name:"201405/How to Add Beautiful Fonts to Any Linux Distribution.md"};function d(m,i,y,b,h,x){const t=s("Link");return p(),f("div",null,[i[16]||(i[16]=l(`<h1 id="如何给任意一款-linux-发行版添加漂亮的字体" tabindex="-1">如何给任意一款 Linux 发行版添加漂亮的字体 <a class="header-anchor" href="#如何给任意一款-linux-发行版添加漂亮的字体" aria-label="Permalink to “如何给任意一款 Linux 发行版添加漂亮的字体”">​</a></h1><p><img src="http://i1-news.softpedia-static.com/images/news2/How-to-Add-Beautiful-Fonts-to-Any-Linux-Distribution-434835-2.jpg" alt=""></p><p><strong>接下来的教程将指导所有 Linux 用户怎么简单的将漂亮的字体添加到自己的操作系统。我们已经为 Debian、Arch Linux、openSUSE、Slackware 和 Fedora 发行版编写了详细的介绍。</strong></p><p>正如许多用户所知，几乎所有基于 Linux 的操作系统主要缺点就是默认选择的字体并不令终端用户满意，尤其是那些从 Windows 或者 Mac OS X 等操作系统迁移过来的用户。</p><p>除了使用自己的一套字体的Ubuntu，从一开始就看起来就相当漂亮，其它所有 Linux 发行版都有字体丑陋的缺点。正因如此，许多用户试图创建一种新的方法来增强文字在各个发行版中渲染效果。</p><p>这就是 Infinality 项目产生的原因，其主要目的是通过添加补丁来为使用任何基于 Linux 操作系统的用户提供最好的字体渲染效果。</p><h3 id="infinality-for-arch-linux" tabindex="-1">Infinality for Arch Linux <a class="header-anchor" href="#infinality-for-arch-linux" aria-label="Permalink to “Infinality for Arch Linux”">​</a></h3><ol><li><p>将infinality-bundle，infinality-bundle-multilib （用于使用64位系统的用户）和infinality-bundle-fonts仓库添加到你的 /etc/pacman.conf文件中：</p><pre><code> [infinality-bundle]
 Server = http://bohoomil.com/repo/$arch

 [infinality-bundle-multilib]
 Server = http://bohoomil.com/repo/multilib/$arch

 [infinality-bundle-fonts]
 Server = http://bohoomil.com/repo/fonts
</code></pre></li><li><p>执行 sudo pacman -Syu 命令用来刷新仓库，然后运行</p><pre><code> sudo pacman -S infinality-bundle infinality-bundle-multilib ibfonts-meta-extended （用于64位系统） 

 sudo pacman -S infinality-bundle ibfonts-meta-extended （用于32位系统）
</code></pre></li><li><p>当被询问是否替换 fontconfig 软件包的 freetype2 时，回答YES。完成后重启你的计算机。</p></li></ol><h3 id="infinality-for-fedora" tabindex="-1">Infinality for Fedora <a class="header-anchor" href="#infinality-for-fedora" aria-label="Permalink to “Infinality for Fedora”">​</a></h3><ol><li><p>在终端窗口中执行如下命令</p><pre><code> sudo rpm -Uvh http://www.infinality.net/fedora/linux/infinality-repo-1.0-1.noarch.rpm
 sudo yum install freetype-infinality fontconfig-infinality
</code></pre></li><li><p>重启你的机器。</p></li></ol><h3 id="infinality-for-opensuse" tabindex="-1">Infinality for openSUSE <a class="header-anchor" href="#infinality-for-opensuse" aria-label="Permalink to “Infinality for openSUSE”">​</a></h3><ol><li><p>添加 Infinality 官方仓库：</p><pre><code> http://download.opensuse.org/repositories/home:/namtrac:/subpixel/openSUSE_13.1/
</code></pre></li></ol><p>打开YaST中的库选项卡，选择namtrac:subpixel仓库，并打击“切换系统包的版本到这个仓库”。</p><ol start="2"><li><p>标记 namtrac:subpixel 中所有还没有安装的包来进行安装，然后从 openSUSE 官方软件仓库中安装 fontconfig-infinality 包。</p></li><li><p>在字体设置选项里将 Subpixel Hinting 选择为“使用系统设置”，或者设置为带有微调的 RGB 顺序。重启你的系统。</p></li></ol><h3 id="infinality-for-slackware" tabindex="-1">Infinality for Slackware <a class="header-anchor" href="#infinality-for-slackware" aria-label="Permalink to “Infinality for Slackware”">​</a></h3>`,15)),o("p",null,[i[1]||(i[1]=n("详细的安装指南：",-1)),e(t,{href:"http://someslack.wordpress.com/infinality-on-slackware/"},{default:a(()=>[...i[0]||(i[0]=[n("http://someslack.wordpress.com/infinality-on-slackware/",-1)])]),_:1})]),i[17]||(i[17]=l(`<h3 id="infinality-for-debian" tabindex="-1">Infinality for Debian <a class="header-anchor" href="#infinality-for-debian" aria-label="Permalink to “Infinality for Debian”">​</a></h3><ol><li><p>在终端中执行下面的命令（一个一个执行，每一行之后敲击回车）：</p><pre><code> echo “deb http://ppa.launchpad.net/no1wantdthisname/ppa/ubuntu raring main” | sudo tee /etc/apt/sources.list.d/infinality.list
 echo “deb-src http://ppa.launchpad.net/no1wantdthisname/ppa/ubuntu raring main” | sudo tee -a /etc/apt/sources.list.d/infinality.list
 sudo apt-key adv --keyserver keyserver.ubuntu.com --recv-keys E985B27B
</code></pre></li><li><p>执行以下命令来升级你的系统并安装 Infinality 包：</p><pre><code> sudo apt-get update
 sudo apt-get upgrade
 sudo apt-get install fontconfig-infinality
</code></pre></li><li><p>重启你的计算机。</p></li></ol>`,2)),o("p",null,[i[3]||(i[3]=n("对于任何文中没有提到的其它 Linux 发行版，请使用官方的介绍：",-1)),e(t,{href:"https://github.com/Infinality/fontconfig-infinality/tree/master/infinality"},{default:a(()=>[...i[2]||(i[2]=[n("https://github.com/Infinality/fontconfig-infinality/tree/master/infinality",-1)])]),_:1}),i[4]||(i[4]=n("。跟以往一样，当你使用本教程过程中遇到任何问题都可以在下面评论，不要犹豫。",-1))]),i[18]||(i[18]=o("hr",null,null,-1)),o("p",null,[i[6]||(i[6]=n("via: ",-1)),e(t,{href:"http://news.softpedia.com/news/How-to-Add-Beautiful-Fonts-to-Any-Linux-Distribution-434835.shtml"},{default:a(()=>[...i[5]||(i[5]=[n("http://news.softpedia.com/news/How-to-Add-Beautiful-Fonts-to-Any-Linux-Distribution-434835.shtml",-1)])]),_:1})]),o("p",null,[i[9]||(i[9]=n("译者：",-1)),e(t,{href:"https://github.com/scusjs"},{default:a(()=>[...i[7]||(i[7]=[n("SCUSJS",-1)])]),_:1}),i[10]||(i[10]=n(" 校对：",-1)),e(t,{href:"https://github.com/carolinewuyan"},{default:a(()=>[...i[8]||(i[8]=[n("Caroline",-1)])]),_:1})]),o("p",null,[i[13]||(i[13]=n("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...i[11]||(i[11]=[n("LCTT",-1)])]),_:1}),i[14]||(i[14]=n(" 原创翻译，",-1)),e(t,{href:"http://linux.cn/"},{default:a(()=>[...i[12]||(i[12]=[n("Linux中国",-1)])]),_:1}),i[15]||(i[15]=n(" 荣誉推出",-1))])])}const L=r(u,[["render",d]]);export{w as __pageData,L as default};
